# Shared by the scripts in this folder; sourced, not run.
#
# A flavor is a directory of $INSTALL_DIR (default ../install) made by
# build.sh from a version of versions.conf:
#   upstream  oneDNN at the PR's base
#   rvjit     oneDNN with the PR (its kernels generated by rvjit)
# Results go to $RESULTS_DIR/<machine>/<flavor>/<kind>/ (default ../results),
# <machine> being the slurm partition, else the host name. Every script
# appends the duration of its phases to $RESULTS_DIR/<machine>/timings.csv.

scripts_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
root_dir=$(cd "$scripts_dir/.." && pwd)
INSTALL_DIR=${INSTALL_DIR:-$root_dir/install}
INPUTS_DIR=${INPUTS_DIR:-$root_dir/inputs}
RESULTS_DIR=${RESULTS_DIR:-$root_dir/results}
FLAVORS=(upstream rvjit)

die() { echo "$(basename "$0"): $*" >&2; exit 2; }

usage() { sed -n '/^# Usage/,/^$/p' "$0" | sed 's/^# \{0,1\}//'; }

# The flavors a command line names: a comma-separated list, or all
flavors_of() {
    local list=$1 f
    [ -z "$list" ] || [ "$list" = all ] && list=$(IFS=,; echo "${FLAVORS[*]}")
    for f in ${list//,/ }; do
        case $f in */*|'') die "bad flavor '$f'" ;; esac
        [ -d "$INSTALL_DIR/$f" ] || die "no install $INSTALL_DIR/$f (scripts/build.sh $f)"
        echo "$f"
    done
}

# The benchdnn --dt argument of a data type of a batch's `# dt:` line: f16 and bf16 alone are
# inputs of that type accumulating into an f32 destination, a:b:c forms pass
# through, `harness` means the batch sets its own (no --dt)
dt_arg() {
    case $1 in
        harness) ;;
        *:*|f32|s8|u8) echo "--dt=$1" ;;
        f16|bf16) echo "--dt=$1:$1:f32" ;;
        *) die "unknown data type '$1'" ;;
    esac
}

# Prints "<driver> <path>" of a batch: inputs/<batch>, whose file name starts
# with the benchdnn driver
resolve_batch() {
    local path=$INPUTS_DIR/$1 name=${1##*/}
    [ -f "$path" ] || die "no batch $path"
    case ${name%%.*} in
        matmul|ip|conv) echo "${name%%.*} $path" ;;
        *) die "$1: the file name must start with matmul., ip. or conv." ;;
    esac
}

# The log name of one run of a batch: <id>.<driver>.<dt>.t<threads>
log_name() {
    local id=$1 driver=$2 dt=$3
    echo "$id.$driver.${dt//:/-}.t$OMP_NUM_THREADS"
}

# Stops unless this is an RV64 machine: the evaluation runs natively only
require_riscv() {
    [ "$(uname -m)" = riscv64 ] \
            || die "runs on an RV64 machine, this is $(uname -m)"
}

host_name() { hostname; }

# The machine results are filed under: the slurm partition, so the nodes of
# one partition share a folder, else the host name
machine_name() { echo "${SLURM_JOB_PARTITION:-$(host_name)}"; }

# The log directory of a flavor's runs of a kind (correctness, perf, perfci,
# ctest)
logs_of() { echo "$RESULTS_DIR/$(machine_name)/$1/$2"; }

# The ISA extensions of this CPU, from /proc/cpuinfo
cpu_isa() { sed -n 's/^isa[[:space:]]*:[[:space:]]*//p' /proc/cpuinfo 2>/dev/null | head -1; }

# Records how a run was made in <logs>/run.env, for the analysis
write_run_env() {
    # oneDNN reports every RV64 CPU as "Generic"; the kernel's ISA string
    # says which extensions the implementations can use
    local flavor=$1 prefix=$2 logs=$3
    {
        echo "machine=$(machine_name)"
        echo "host=$(host_name)"
        echo "flavor=$flavor"
        echo "revision=$(head -1 "$prefix/REVISION" 2>/dev/null)"
        echo "threads=$OMP_NUM_THREADS"
        echo "cpu_isa=$(cpu_isa)"
        echo "cpu_model=$(sed -n 's/^\(model name\|uarch\)[[:space:]]*:[[:space:]]*//p' /proc/cpuinfo 2>/dev/null | head -1)"
        echo "job=${SLURM_JOB_ID:--}"
        echo "date=$(date -Iseconds)"
    } > "$logs/run.env"
}

# Prints the header of one flavor's run
print_header() {
    local flavor=$1 prefix=$2
    echo "=== $flavor: $(head -1 "$prefix/REVISION" 2>/dev/null || echo "$prefix")"
    echo "=== host $(host_name) job ${SLURM_JOB_ID:--} threads $OMP_NUM_THREADS"
}

# Timing. phase_begin PHASE FLAVOR ITEM starts a phase, phase_end RC ends the
# innermost one and appends it to timings.csv; phase_report prints the
# totals of this script's phases. Phases nest.
TIMINGS_FILE=${TIMINGS_FILE:-}
RUN_ID=${RUN_ID:-$(basename "$0" .sh)-$(date +%Y%m%dT%H%M%S)-$$}
_phase_stack=()

timings_file() {
    [ -n "$TIMINGS_FILE" ] || TIMINGS_FILE=$RESULTS_DIR/$(machine_name)/timings.csv
    mkdir -p "$(dirname "$TIMINGS_FILE")"
    # Concurrent jobs share the file: only the one that creates it writes the
    # header (noclobber)
    [ -s "$TIMINGS_FILE" ] || (set -C
        echo "run,phase,flavor,item,host,threads,start,end,seconds,rc" > "$TIMINGS_FILE"
    ) 2> /dev/null || true
    echo "$TIMINGS_FILE"
}

phase_begin() {
    _phase_stack+=("$1|$2|$3|$(date -Iseconds)|$(date +%s.%N)")
}

phase_end() {
    local rc=${1:-0} top=$((${#_phase_stack[@]} - 1)) phase flavor item start t0 secs
    [ $top -ge 0 ] || return 0
    IFS='|' read -r phase flavor item start t0 <<< "${_phase_stack[$top]}"
    unset "_phase_stack[$top]"
    _phase_stack=("${_phase_stack[@]}")
    secs=$(awk -v a="$t0" -v b="$(date +%s.%N)" 'BEGIN { printf "%.1f", b - a }')
    # A list of flavors (the whole run) is space-separated in the CSV
    echo "$RUN_ID,$phase,${flavor//,/ },\"$item\",$(host_name),${OMP_NUM_THREADS:-},$start,$(date -Iseconds),$secs,$rc" \
            >> "$(timings_file)"
}

phase_report() {
    local f
    f=$(timings_file)
    awk -F, -v run="$RUN_ID" '$1 == run {
            if (!($2 in t)) order[n++] = $2
            t[$2] += $9; c[$2]++ }
        END { if (n) print "=== time per phase (" run ")"
              for (i = 0; i < n; i++)
                  printf "%-14s %4d x  %9.1fs\n", order[i], c[order[i]], t[order[i]] }' "$f"
}
